fn solve(n: i8) -> Vec<char> {
    // Since we only need to use 'a' and 'b' 
    // and must ensure that s[i] != s[i+2] for 0 <= i <= n-3,
    // a simple alternating pattern like "ababa..." works perfectly.
    // Because s[i] and s[i+2] will be different characters.
    //
    // For example:
    // index: 0 1 2 3 4 5
    // chars: a b a b a b
    // Check s[0] != s[2] => 'a' != 'a' ? false. 
    // Wait, so "ababa" looks like s[0] == s[2] == 'a'
    //
    // We need that s[i] != s[i+2].
    // If pattern is "ababab", s[0] = 'a' and s[2] = 'a', 
    // which violates the rule.
    //
    // So alternating alone fails.
    //
    // Let's try a pattern of length 3 to repeat, for example: "abc"
    // But we must not use 'c'.
    //
    // We can consider a period-2 sequence of length 3:
    // Let's try pattern "ab", sequence "ababab..."
    // s[i] != s[i+2] means:
    // s[0] != s[2], s[0] = 'a', s[2] = 'a' --> fails.
    //
    // Next try pattern with length 4: "abba"
    // s[0] = 'a', s[2] = 'b' => OK
    // s[1] = 'b', s[3] = 'a' => OK
    //
    // So pattern "abba" repeats:
    // for indexes 0..n:
    // s[i] = 'a' if i % 4 == 0 or i % 4 == 3
    // else 'b'
    //
    // Let's check s[i] != s[i+2]:
    // i = 0: s[0] = 'a', s[2] = 'b' -> different
    // i = 1: s[1] = 'b', s[3] = 'a' -> different
    // i = 2: s[2] = 'b', s[4] = 'a' -> different
    // i = 3: s[3] = 'a', s[5] = 'b' -> different
    //
    // Perfect! Plus only 'a' and 'b' are used, no 'c'.
    
    let mut result = Vec::with_capacity(n as usize);
    for i in 0..n {
        let ch = match i % 4 {
            0 | 3 => 'a',
            _ => 'b',
        };
        result.push(ch);
    }
    result
}